		try {
			Files.createDirectories(file.getParent());
			temporary = Files.createTempFile(file.getParent(), FILE_NAME, ".tmp");
			Files.write(temporary, lines, StandardCharsets.UTF_8);
			try (FileChannel channel = FileChannel.open(temporary, StandardOpenOption.WRITE)) {
				channel.force(true);
			}
			try {
				Files.move(temporary, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			} catch (AtomicMoveNotSupportedException unsupported) {
				Files.move(temporary, file, StandardCopyOption.REPLACE_EXISTING);
			}
			temporary = null;
		} catch (IOException | RuntimeException failure) {
			dirty = true;
			logger.warn("LMDB advisory learner could not write {}: {}", file, failure.toString());
		} finally {
			if (temporary != null) {
				try {
					Files.deleteIfExists(temporary);
				} catch (IOException ignored) {
					logger.debug("LMDB advisory learner left a temporary file behind: {}", temporary);
				}
			}
		}
